ublic, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"2279","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"proallargtypes":null,"pronargdefaults":0},"language":"plpgsql","body":"8d2bf69857323591892c3956cdd2fedd3d227cf042c928c56fc714e4ff957f24","defaultExpression":null,"app":false,"public":false},{"signature":"guard_session_context_lineage()","metadata":{"probin":null,"procost":100,"prokind":"f","proname":"guard_session_context_lineage","prorows":0,"pronargs":0,"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"2279","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"proallargtypes":null,"pronargdefaults":0},"language":"plpgsql","body":"970b284e9d53ffffc75c68415b3fcf53137fff1c7de3dd611faaae369d75e38e","defaultExpression":null,"app":false,"public":false},{"signature":"enqueue_native_field_dependency_work()","metadata":{"probin":null,"procost":100,"prokind":"f","proname":"enqueue_native_field_dependency_work","prorows":0,"pronargs":0,"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"2279","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"proallargtypes":null,"pronargdefaults":0},"language":"plpgsql","body":"63dc6fda9666c35341d214c9b1fc524199d8cfea85f41b610e2d5e1203487219","defaultExpression":null,"app":false,"public":false},{"signature":"validate_native_field_dependency_batch(uuid,uuid,jsonb)","metadata":{"probin":null,"procost":100,"prokind":"f","proname":"validate_native_field_dependency_batch","prorows":0,"pronargs":3,"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"16","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["w","derivation","work"],"proargtypes":["2950","2950","3802"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"proallargtypes":null,"pronargdefaults":0},"language":"plpgsql","body":"c5a69af10d0a81765d3a27c489dbf55b0ef9ebcc7fa334303e966c4eb5b5634b","defaultExpression":null,"app":false,"public":false}]'::jsonb) LOOP
 SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure('public.'||(expected->>'signature'));
 IF actual.oid IS NULL OR pg_get_expr(actual.proargdefaults,0) IS DISTINCT FROM expected->>'defaultExpression'
 OR expected->>'body' IS NOT NULL AND encode(sha256(convert_to(actual.prosrc,'UTF8')),'hex') IS DISTINCT FROM expected->>'body'
 OR actual.proowner IS DISTINCT FROM (SELECT relowner FROM pg_class WHERE oid='public.memories'::regclass)
 OR actual.pronamespace<>'public'::regnamespace OR actual.prolang IS DISTINCT FROM (SELECT oid FROM pg_language WHERE lanname=expected->>'language')
 OR (to_jsonb(actual)-ARRAY['oid','prosrc','proowner','proacl','prolang','pronamespace','proargdefaults']) IS DISTINCT FROM expected->'metadata'
 OR NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(actual.proacl,acldefault('f',actual.proowner))) a WHERE a.grantee=actual.proowner AND a.grantor=actual.proowner AND a.privilege_type='EXECUTE' AND NOT a.is_grantable)
 OR EXISTS(SELECT 1 FROM aclexplode(coalesce(actual.proacl,acldefault('f',actual.proowner))) a WHERE a.grantor<>actual.proowner OR a.privilege_type<>'EXECUTE' OR a.is_grantable OR a.grantee<>actual.proowner
  AND NOT(a.grantee=0 AND (expected->>'public')::boolean)
  AND NOT(a.grantee<>0 AND (expected->>'app')::boolean AND EXISTS(SELECT 1 FROM pg_roles WHERE oid=a.grantee AND rolname='app_user')))
 OR (expected->>'app')::boolean AND EXISTS(SELECT 1 FROM pg_roles WHERE rolname='app_user') AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(actual.proacl,acldefault('f',actual.proowner))) a JOIN pg_roles r ON r.oid=a.grantee WHERE r.rolname='app_user' AND a.privilege_type='EXECUTE')
 OR (expected->>'public')::boolean AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(actual.proacl,acldefault('f',actual.proowner))) a WHERE a.grantee=0 AND a.privilege_type='EXECUTE')
 THEN RAISE EXCEPTION 'Detached evaluator prerequisite metadata changed: %',expected->>'signature';END IF;
 END LOOP;
END $additional_closure$;
DO $edge_transition$
DECLARE actual pg_proc;expected jsonb;dependency jsonb;pins text;trusted text;pin_count integer;trigger_state jsonb;table_state jsonb;shape_sql text;body text;fk_query text;fk_state jsonb;old_pin text;new_pin text;definition text;original_pins jsonb;original_bodies jsonb;original_metadata jsonb;lineage_values text;semantic_hash text;columns_sql text;row_sql text;comparisons text;catalog_shape jsonb;rows_sql text;actual_oids oid[];
BEGIN
 -- Reconstruct the existing SQL guard before invoking it. Its catalog
 -- fingerprints are data; the executable template is fixed by migration8152.
 SELECT string_agg(format('(%s::oid,%L::text)',p.oid,encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex')),',' ORDER BY p.oid)
 INTO pins FROM pg_proc p WHERE oid IN(
  'application_empty_query_worklist_reset(jsonb)'::regprocedure,
  'application_empty_query_worklist_current(uuid,jsonb)'::regprocedure,
  'read_native_empty_query_session_evidence(uuid,text[],uuid[],text[],boolean)'::regprocedure,
  'application_field_envelope_ancestry_allowed(uuid,jsonb)'::regprocedure);
 trusted:='SELECT application_memory_statement_helpers_current() AND (SELECT count(*)=4 AND coalesce(bool_and(encode(sha256(convert_to(to_jsonb(p)::text,''UTF8'')),''hex'')=pin.fingerprint),false)
    FROM (VALUES '||pins||') pin(function_oid,fingerprint) JOIN pg_catalog.pg_proc p ON p.oid=pin.function_oid)';
 SELECT * INTO actual FROM pg_proc WHERE oid='application_empty_query_helpers_current()'::regprocedure;
 IF actual.prosrc IS DISTINCT FROM trusted OR actual.proowner<>(SELECT relowner FROM pg_class WHERE oid='public.memories'::regclass)
  OR actual.prolang<>(SELECT oid FROM pg_language WHERE lanname='sql') OR actual.pronamespace<>'public'::regnamespace
  OR NOT actual.prosecdef OR actual.provolatile<>'v' OR actual.proparallel<>'u' OR actual.procost<>100 OR actual.prorows<>0
  OR actual.prokind<>'f' OR actual.prorettype<>'boolean'::regtype OR actual.proretset OR actual.proisstrict OR actual.proleakproof
  OR actual.proconfig IS DISTINCT FROM ARRAY['search_path=pg_catalog, public, pg_temp'] OR actual.prosupport<>0
  OR actual.probin IS NOT NULL OR actual.prosqlbody IS NOT NULL OR actual.proargdefaults IS NOT NULL OR actual.pronargdefaults<>0
  OR actual.proargnames IS NOT NULL OR actual.proargmodes IS NOT NULL OR actual.proallargtypes IS NOT NULL OR actual.protrftypes IS NOT NULL
  OR EXISTS(SELECT 1 FROM aclexplode(coalesce(actual.proacl,acldefault('f',actual.proowner))) a
   WHERE a.grantee<>actual.proowner OR a.grantor<>actual.proowner OR a.privilege_type<>'EXECUTE' OR a.is_grantable)
 THEN RAISE EXCEPTION 'Native dependency existing guard changed';END IF;

 SELECT string_agg(format('(%s::oid,%L::text)',p.oid,encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex')),',' ORDER BY p.oid)
 INTO pins FROM pg_proc p WHERE oid IN(
  'read_native_file_session_cohort_frame(uuid,text[],uuid[],text[],boolean)'::regprocedure,
  'application_native_file_frame_current(uuid,text[],uuid[],text[],jsonb)'::regprocedure,
  'read_native_file_session_field_snapshots(uuid,uuid[],text[])'::regprocedure,
  'capture_native_session_projection_batch(uuid,uuid,integer,text)'::regprocedure,
