teger,integer)'::regprocedure,'public.read_session_context_empty_query_revision(uuid,uuid)'::regprocedure,'public.read_session_context_file_revision(uuid,uuid)'::regprocedure,'public.session_context_empty_query_revision_allowed(uuid,uuid)'::regprocedure,'public.session_context_file_revision_allowed(uuid,uuid)'::regprocedure,'public.validate_application_field_dependencies()'::regprocedure) LOOP
 IF (to_jsonb(actual)-'prosrc') IS DISTINCT FROM original_metadata->(actual.oid::text) THEN RAISE EXCEPTION 'Detached evaluator metadata changed during transition: %',actual.oid::regprocedure;END IF;
 END LOOP;

 IF application_empty_query_facades_current() IS NOT TRUE OR application_memory_statement_helpers_current() IS NOT TRUE OR application_native_context_fields_current() IS NOT TRUE OR application_native_covered_evidence_helpers_current() IS NOT TRUE OR application_native_dependency_batch_helpers_current() IS NOT TRUE OR application_native_field_reference_helpers_current() IS NOT TRUE OR application_native_file_capture_helpers_current() IS NOT TRUE OR application_native_session_query_acquisition_current() IS NOT TRUE OR application_native_title_acquisition_helpers_current() IS NOT TRUE OR application_native_title_group_helpers_current() IS NOT TRUE OR application_native_transcript_prepare_helpers_current() IS NOT TRUE OR application_native_worklist_helpers_current() IS NOT TRUE THEN RAISE EXCEPTION 'Detached evaluator final manifests unavailable';END IF;
END $edge_transition$;
COMMIT;
